import React, { useEffect, useState } from "react";
import detailsOfSelLetter from "../Sentence.json";
import { useNavigate } from "react-router-dom";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import ReactGA from "react-ga4";
import Swal from "sweetalert2";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";

const Level2MidContent = () => {
  const parse = require("html-react-parser").default;
  const [pageName, setpageName] = useState("Level-2");
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  let [skipCount, setSkipCount] = useState(0);
  const navigate = useNavigate();
  var [finalIdxActHiddnWordSent, setIdxActHiddnWordSent] = useState([]);
  // Details of Complete List of Hidden Words Found
  var [finalCompleteList, setFinalCompleteList] = useState([]);
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  let [answerArray, setAnswerArray] = useState([]);
  let [selectedAns, setSelectedAns] = useState([]);
  let [showMessage, setShowMessage] = useState(false);
  let [fbMessage, setFbMessage] = useState("");
  const [level, setLevel] = useState("Level 2");
  let [disabledNext, setDisabledNext] = useState(true);

  function randomNumberInRange(min, max) {
    return Math.floor(Math.random() * (max - min)) + min;
  }

  const validate = () => {
    let allGreen = true; // Flag to track if all dropdowns are green

    finalCompleteList.forEach((word) => {
      if (word !== "") {
        const elementsByName = document.getElementsByName(word);

        for (const inputElement of elementsByName) {
          const valueOfInput = inputElement.value;

          if (word === valueOfInput) {
            inputElement.style.backgroundColor = "green";
            inputElement.style.color = "white";
          } else {
            inputElement.style.backgroundColor = "red";
            inputElement.style.color = "white";
            allGreen = false; // If any dropdown is red, set flag to false
          }
        }
      }
    });

    // Enable the "Next" button if all dropdowns are green
    if (allGreen) {
      setDisabledNext(false);
      Swal.fire({
        title: "Correct!",
        customClass: {
          title: "green-text",
          htmlContainer: "green-text",
        },
      });
    } else {
      setDisabledNext(true); // Disable "Next" button if not all are green
      console.log("Some answers are incorrect. Please review.");
    }
  };

  function getDetailsOfHiddenWords(mapOfDetails) {
    var idxHiddenWord = [];
    var listOfHiddenWords = [];
    var idxActHddnWordSent = [];

    // Start : Load content of From Sentence Map ..........
    mapOfDetails.map((item, idx) => {
      var sentHiddenWords = item.hidden;
      var hiddenLen = sentHiddenWords.length;

      if (hiddenLen === 0 || (hiddenLen === 1 && sentHiddenWords[0] === "")) {
        idxHiddenWord.push(-1);
        listOfHiddenWords.push("");
        idxActHddnWordSent.push(-1);
      } else {
        var hiddenIdx = randomNumberInRange(0, hiddenLen);
        var sentsplit = ([] = item.sentence.split(" "));
        idxHiddenWord.push(hiddenIdx);

        if (sentsplit.includes(sentHiddenWords[hiddenIdx])) {
          var hiddenWord =
            sentsplit[sentsplit.indexOf(sentHiddenWords[hiddenIdx])];
          var idxTemp = sentsplit.indexOf(sentHiddenWords[hiddenIdx]);
          listOfHiddenWords.push(hiddenWord);
          idxActHddnWordSent.push(idxTemp);
        }
      }
    });
    // End : Load content of From Sentence Map ..........

    var finResult = {
      idxHiddenWord: idxHiddenWord,
      listOfHiddenWords: listOfHiddenWords,
      idxActHddnWordSent: idxActHddnWordSent,
    };
    return finResult;
  }
  // Display content of body
  useEffect(() => {
    if (detailsOfSelLetter.level2[randomNumber].length !== 0) {
      // Start : Load content of Body ..........
      var letterBodyDetails = getDetailsOfHiddenWords(
        detailsOfSelLetter.level2[randomNumber].body
      );
      setIdxActHiddnWordSent([...letterBodyDetails.idxActHddnWordSent]);
      // End : Load content of Body ............

      var completedWordList = [...letterBodyDetails.listOfHiddenWords];

      //Shuffle list of words for random display ...
      // completedWordList.sort(() => 0.5 - Math.random());
      setFinalCompleteList([...completedWordList]);
    }

    //inserting first dropdown element as it is into an selectedAnsArray
    selectedAns.push(detailsOfSelLetter.level2[randomNumber].hiddenWords[0]);
    setAnswerArray([...detailsOfSelLetter.level2[randomNumber].hiddenWords]);
  }, [randomNumber]);

  const handleNext = () => {
    setDisabledNext(true);
    finalCompleteList.forEach((word) => {
      if (word !== "") {
        var listOfElementbyName = document.getElementsByName(word);
        for (var i = 0; i < listOfElementbyName.length; i++) {
          document.getElementsByName(word)[i].style.backgroundColor = "";
          document.getElementsByName(word)[i].style.color = "";
        }
      }
    });

    setSelectedAns([]);
    setFinalCompleteList([]);
    randomNumber = Math.floor(Math.random() * detailsOfSelLetter.level2.length);
    if (randomNumberArray.length !== 5) {
      if (randomNumberArray.includes(randomNumber)) {
        handleNext();
      } else {
        setRandomNumberArray((prevState) => [...prevState, randomNumber]);
        setRandomNumber(randomNumber);
      }
    } else {
      Swal.fire({
        title: `You have successfully attempted ${
          5 - skipCount
        } out of 5 paraghaphs!`,
        showClass: {
          popup: "animate__animated animate__fadeInDown",
        },
        hideClass: {
          popup: "animate__animated animate__fadeOutUp",
        },
        customClass: {
          title: "completeion-text",
          htmlContainer: "completeion-text",
        },
        confirmButtonText: "Restart",
      }).then((result) => {
        if (result.isConfirmed) {
          navigate("/");
        }
      });
    }

    ReactGA.event({
      action: `Eng10|Pronoun|Clicked on "NEXT" button of level-2`,
      category: `Eng10|next button clicked`,
      label: `Eng10|Clicked on next button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "NEXT",
      "Clicked",
      "Clicked to move to the next sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    handleNext();

    ReactGA.event({
      action: `Eng10|Pronoun|Clicked on "SKIP" button of level-2`,
      category: `Eng10|SKIP button clicked`,
      label: `Eng10|Clicked on SKIP button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "SKIP",
      "Clicked",
      "Clicked to skip the sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleChange = (event) => {
    setLevel(event.target.value);
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        ReactGA.event({
          action: `Eng10|Pronoun|Clicked on dropdown to navigate to the level-1`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-1",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level1/level2");
        ReactGA.event({
          action: `Eng10|Pronoun|Clicked on dropdown to navigate to the level-2`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-2",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
    }
  };

  const handledropdownchange = (event, index) => {
    selectedAns[index] = event.target.value;

    if (answerArray[index] !== selectedAns[index]) {
      setFbMessage(
        detailsOfSelLetter.level2[randomNumber].body[index].feedback[
          event.target.value
        ]
      );
      setShowMessage(true);
    } else {
      setShowMessage(false);
    }
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex justify-content-center align-items-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
          }}
        >
          <div className="row mb-3 sticky-top">
            <div className="d-flex justify-content-end">
              <FormControl size="small">
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level} // Step 3: Set the value prop
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green", // Set background color
                    borderRadius: "8px", // Set border radius
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green", // Set border color if needed
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">Level 1</MenuItem>
                  <MenuItem value="Level 2">Level 2</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>

          <div className="row mb-3">
            <div className="d-flex align-items-center">
              <span className="me-3">Paragraph</span>

              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={5}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomNumberArray.length}/{5}
              </span>
            </div>
          </div>
          <div className="" style={{ height: "auto" }}>
            <div
              className="row-md-auto"
              style={{
                height: "auto",
                borderRadius: "20px",
                backgroundColor: "#FCF5F5",
                borderRadius: "5px",
                border: "1px solid #BAB7BD",
              }}
            >
              <div
                className="row"
                style={{
                  borderRadius: "8px",
                  marginLeft: "0.1%",
                  marginRight: "0.1%",
                  paddingLeft: "1%",
                  paddingTop: "1%",
                }}
              >
                <div
                  className="row-md-auto overflow-auto"
                  style={{ height: "90%" }}
                >
                  {/* ################ Body : Start : Display the contents of the Body ################### */}

                  <div className="row-md-auto wrap">
                    <div
                      style={{
                        maxWidth: "100%",
                        display: "inline-flex",
                        flexWrap: "wrap",
                        textAlign: "left",
                        margin: "0 auto",
                        lineHeight: "30px",
                      }}
                    >
                      {detailsOfSelLetter.level2[randomNumber].body.map(
                        (slotitem, index1) =>
                          slotitem.sentence.split(" ").map((word, index) => (
                            <>
                              {finalIdxActHiddnWordSent[index1] === index ? (
                                <select
                                  className="selectdropdown"
                                  name={word}
                                  onChange={(e) =>
                                    handledropdownchange(
                                      e,
                                      slotitem.sent_id - 1,
                                      slotitem.hidden
                                    )
                                  }
                                >
                                  {Object.keys(slotitem.options).map(
                                    (optionKey, idx) => (
                                      <>
                                        {optionKey === word ? (
                                          <>
                                            {slotitem.options[optionKey].map(
                                              (optionWord, optionidx) => (
                                                <option
                                                  key={optionidx}
                                                  value={optionWord}
                                                >
                                                  {optionWord}
                                                </option>
                                              )
                                            )}
                                          </>
                                        ) : (
                                          <></>
                                        )}
                                      </>
                                    )
                                  )}
                                </select>
                              ) : (
                                <div
                                  key={
                                    "body_" + word + "_" + index1 + "_" + index
                                  }
                                  style={{
                                    minWidth: "20px",
                                    paddingRight: "5px",
                                    marginBottom: "0.5%",
                                    marginTop: "0.5%",
                                  }}
                                >
                                  {word}
                                </div>
                              )}
                            </>
                          ))
                      )}
                    </div>
                  </div>
                  {/* ################ Body : End : Display the contents of the Body ################### */}
                </div>
              </div>
            </div>
            <div className="d-flex justify-content-around mt-3 mb-5">
              <Button variant="contained" onClick={handleSkip}>
                Skip
              </Button>
              <Button variant="contained" onClick={validate} color="success">
                Verify
              </Button>
              <Button
                variant="contained"
                onClick={handleNext}
                disabled={disabledNext}
              >
                {randomNumberArray.length == 5 ? "FINISH" : "NEXT"}
              </Button>
            </div>
            <div className="row justify-content-center">
              {showMessage && (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "#ffffff",
                    boxShadow: "0px 0px 10px rgba(255, 0, 0, 0.5)",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  <div>{parse(fbMessage)}</div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
      <div className="col-sm-3 d-flex justify-content-center align-items-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            Instructions
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <div>
              <ul>
                <li>
                  Select the correct pronoun from the dropdown on the place of
                  the subject.
                </li>{" "}
                <li>Click on the "VERIFY" button to verify the selection.</li>
                <li>Click on the "NEXT" button to get the next paragraph.</li>
                <li>Click on the "SKIP" button to skip the paragraph.</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level2MidContent;
