import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";
import React, { useState } from "react";
import data from "../Sentence.json";
import { toast } from "react-toastify";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import ReactGA from "react-ga4";

const Level1MidContent = () => {
  const [pageName, setpageName] = useState("Level-1");
  const parse = require("html-react-parser").default;
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  let [showMessage, setShowMessage] = useState(false);
  const [selectedOption, setSelectedOption] = useState("");
  const navigate = useNavigate();
  let [skipCount, setSkipCount] = useState(0);
  let [isNextDisable, setIsNextDisable] = useState(true);
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [level, setLevel] = useState("Level 1");

  function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  const handleDropdownChange = (event) => {
    setShowMessage(false);
    setSelectedOption(event.target.value);
  };

  const handleVerify = () => {
    if (selectedOption) {
      if (selectedOption == data.level1[randomNumber].answer) {
        setIsNextDisable(false);
        setShowMessage(true);
      } else {
        setShowMessage(true);
      }
    } else {
      toast.error("Please select an option!", {
        position: "top-center",
        autoClose: 2000,
      });
    }
    ReactGA.event({
      action: `Eng10|Pronoun|Clicked on "verify" button of level-1`,
      category: `Eng10|verify button clicked`,
      label: `Eng10|Clicked on verify button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Verify",
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleNext = () => {
    setIsNextDisable(true);
    setSelectedOption("");
    setShowMessage(false);
    randomNumber = Math.floor(Math.random() * data.level1.length);
    if (randomNumberArray.length !== 10) {
      if (randomNumberArray.includes(randomNumber)) {
        handleNext();
      } else {
        setRandomNumberArray((prevState) => [...prevState, randomNumber]);
        setRandomNumber(randomNumber);
      }
    } else {
      Swal.fire({
        title: `You have successfully attempted ${
          10 - skipCount
        } out of 10 sentences!`,
        showClass: {
          popup: "animate__animated animate__fadeInDown",
        },
        hideClass: {
          popup: "animate__animated animate__fadeOutUp",
        },
        customClass: {
          title: "completeion-text",
          htmlContainer: "completeion-text",
        },
        confirmButtonText: "Proceed to Level-2",
      }).then((result) => {
        if (result.isConfirmed) {
          navigate("/launchpage/englishactivity/level1/level2");
        }
      });
    }

    ReactGA.event({
      action: `Eng10|Pronoun|Clicked on "NEXT" button of level-1`,
      category: `Eng10|next button clicked`,
      label: `Eng10|Clicked on next button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "NEXT",
      "Clicked",
      "Clicked to move to the next sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleChange = (event) => {
    setLevel(event.target.value);
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        ReactGA.event({
          action: `Eng10|Pronoun|Clicked on dropdown to navigate to the level-1`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-1",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level1/level2");
        ReactGA.event({
          action: `Eng10|Pronoun|Clicked on dropdown to navigate to the level-2`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-2",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
      case "level3":
        navigate("/launchpage/englishactivity/level1/level2/level3");
        ReactGA.event({
          action: `Eng10|Pronoun|Clicked on dropdown to navigate to the level-3`,
          category: `Eng10|level Dropdown clicked`,
          label: `Eng10|Clicked on Level Dropdown`,
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          "Dropdown",
          "Clicked",
          "Clicked to navigate to level-3",
          [{ input: "", answer: "", result: "" }],
          [
            {
              popuptype: "",
              popuptext: "",
            },
          ],
          [{ hint: "" }]
        );
        break;
    }
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    handleNext();

    ReactGA.event({
      action: `Eng10|Pronoun|Clicked on "SKIP" button of level-1`,
      category: `Eng10|SKIP button clicked`,
      label: `Eng10|Clicked on SKIP button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "SKIP",
      "Clicked",
      "Clicked to skip the sentence",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
          }}
        >
          <div className="row mb-5 sticky-top">
            <div className="d-flex justify-content-end">
              <FormControl size="small">
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">Level 1</MenuItem>
                  <MenuItem value="Level 2">Level 2</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>
          <div className="row mb-5">
            <div className="d-flex align-items-center">
              <span className="me-3">Sentence</span>

              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={10}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomNumberArray.length}/{10}
              </span>
            </div>
          </div>
          <div
            className="row text-center mb-5"
            style={{
              background:
                "transparent linear-gradient(268deg, #FDBD23 0%, #F7B94E 100%) 0% 0% no-repeat padding-box",
              borderRadius: "40px",
              boxShadow: "0px 3px 6px #00000029",
              color: "#000000",
              opacity: "1",
              padding: "2%",
            }}
          >
            <div className="fw-bolder">
              {data.level1[randomNumber].sentence
                .split(" ")
                .map((item, index) => (
                  <>
                    {item == data.level1[randomNumber].answer ? (
                      <select
                        value={selectedOption}
                        onChange={handleDropdownChange}
                        style={{ cursor: "pointer" }}
                      >
                        <option value="">Select an option</option>
                        {shuffleArray(data.level1[randomNumber].options).map(
                          (option, optionIndex) => (
                            <option key={optionIndex} value={option}>
                              {option}
                            </option>
                          )
                        )}
                      </select>
                    ) : (
                      <> {item} </>
                    )}
                  </>
                ))}
            </div>
          </div>
          <div className="row mb-5">
            <div className="d-flex justify-content-around">
              <Button variant="contained" onClick={handleSkip}>
                Skip
              </Button>
              <Button
                color="success"
                variant="contained"
                onClick={handleVerify}
              >
                Verify
              </Button>
              <Button
                disabled={isNextDisable}
                variant="contained"
                onClick={handleNext}
              >
                {randomNumberArray.length == 10 ? "FINISH" : "NEXT"}
              </Button>
            </div>
          </div>
          <div className="row justify-content-center">
            {showMessage && (
              <div
                className="d-flex justify-content-center align-items-center"
                style={{
                  width: "auto",
                  height: "auto",
                  background: "#ffffff",
                  boxShadow: "0px 0px 10px rgba(0, 0, 0, 0.5)",
                  borderRadius: "50px",
                  padding: "2%",
                }}
              >
                <div>{parse(data.level1[randomNumber][selectedOption])}</div>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            Instructions
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <div>
              <ul>
                <li>Select the correct pronoun from the dropdown.</li>
                <li>Click on the "VERIFY" button to verify the selection.</li>
                <li>Click on the "NEXT" button to get the next sentence.</li>
                <li>Click on the "SKIP" button to skip the sentence.</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level1MidContent;
